import * as React from "react";
import { AppBar, Toolbar, Typography, Box, Button, IconButton, TextField, Slide, Avatar } from "@mui/material";
import HomeIcon from "@mui/icons-material/Home";
import SearchIcon from "@mui/icons-material/Search";
import MessageIcon from "@mui/icons-material/Message";
import PersonIcon from "@mui/icons-material/Person";
import ShoppingCartIcon from "@mui/icons-material/ShoppingCart";
import CloseIcon from "@mui/icons-material/Close";
import { useNavigate } from "react-router-dom";

interface NavigationBarProps {
  onSelect?: (page: string) => void;
  activePage: number;
}

export default function NavigationBar({ onSelect, activePage }: NavigationBarProps) {
  const navigate = useNavigate();
  const [searchOpen, setSearchOpen] = React.useState(false);
  const [searchQuery, setSearchQuery] = React.useState("");
  const [selectedDate, setSelectedDate] = React.useState<string | null>(null);

  const menuItems = [
    { label: "Home", value: "home" },
    { label: "Venues", value: "venues" },
    { label: "Hair", value: "hair" },
    { label: "Makeup", value: "makeup" },
    { label: "Photographers", value: "photographers" },
    { label: "Music", value: "music" },
    { label: "Florist", value: "florist" },
    { label: "Dresser", value: "dresser" },
    { label: "Planner", value: "planner" },
  ];

  // Get the selected date from localStorage when the component mounts
  React.useEffect(() => {
    const storedDate = localStorage.getItem("selectedDate");
    if (storedDate) {
      setSelectedDate(storedDate);
    }
  }, []);

  const handleMenuItemClick = (index: number) => {
    if (onSelect) {
      onSelect(menuItems[index].value);
    }

    // Check if the clicked item is "Home" (either logo or home icon)
    if (index === 0) {
      setSelectedDate(null); // Reset date when navigating to home
    }
  };

  const handleDateClick = () => {
    navigate("/calendar"); // Navigate back to the calendar to select a new date
  };

  const handleLogoClick = () => {
    handleMenuItemClick(0); // Trigger the same behavior as clicking "Home" menu item
  };

  return (
    <>
      {/* Top Navigation Bar */}
      <AppBar
        position="fixed"
        color="transparent"
        elevation={0}
        sx={{
          top: "10px", // Adjusted to start a little lower
          zIndex: 1200,
          backgroundColor: "transparent",
          backdropFilter: "blur(10px)",
        }}
      >
        <Toolbar sx={{ display: "flex", alignItems: "center", paddingX: 4 }}>
          {/* "E" Logo Placeholder on the left, with navigation to home */}
          <Avatar
            sx={{
              width: 40,
              height: 40,
              bgcolor: "#a58b84",
              marginRight: 2, // Space between the logo and date
              cursor: "pointer", // To show it's clickable
            }}
            onClick={handleLogoClick} // Show homepage content on click
          >
            E
          </Avatar>

          {/* Display the selected date in the navigation bar */}
          <Typography
            variant="h6"
            sx={{
              fontWeight: "bold",
              textTransform: "uppercase",
              cursor: "pointer",
              flexGrow: 1,
              textAlign: "center",
              color: "#000",
            }}
            onClick={handleDateClick} // Navigate back to the calendar on click
          >
            {selectedDate || "Select Date"}
          </Typography>

          <Box sx={{ display: "flex", alignItems: "center" }}>
            <IconButton color="inherit" onClick={() => setSearchOpen(!searchOpen)}>
              <SearchIcon sx={{ fontSize: "28px", color: "#000" }} />
            </IconButton>
            <IconButton color="inherit">
              <ShoppingCartIcon sx={{ fontSize: "28px", color: "#000" }} />
            </IconButton>
          </Box>
        </Toolbar>
        <Box
          sx={{
            display: "flex",
            overflowX: "auto",
            flexGrow: 1,
            justifyContent: "flex-start",
            paddingX: 2,
            width: "100%",
            flexWrap: "nowrap",
            "&::-webkit-scrollbar": { display: "none" },
          }}
        >
          {menuItems.map((item, index) => (
            <Button
              key={item.value}
              color="inherit"
              sx={{
                textTransform: "uppercase",
                fontWeight: 500,
                fontSize: "14px",
                paddingX: 2,
                minWidth: "max-content",
                backgroundColor: activePage === index ? "#6B4F4F" : "transparent",
                color: activePage === index ? "#fff" : "#000",
                borderRadius: "5px",
                transition: "background-color 0.3s ease-in-out, color 0.3s ease-in-out",
              }}
              onClick={() => handleMenuItemClick(index)}
            >
              {item.label}
            </Button>
          ))}
        </Box>
      </AppBar>

      {/* Conditionally Render Homepage Content Below Navbar */}
      {activePage === 0 && (
        <Box sx={{ paddingTop: "120px", paddingX: 2 }}>
          <Typography variant="h4" sx={{ marginBottom: 2 }}>
            Welcome to the Homepage
          </Typography>
          <Typography variant="body1">
            This is the content of the homepage. You can add your homepage content here.
          </Typography>
        </Box>
      )}

      {/* Search Bar (Perfectly Centered Below Navbar) */}
      <Slide direction="down" in={searchOpen} mountOnEnter unmountOnExit>
        <Box
          sx={{
            position: "fixed",
            top: "100px", // Lowered so it doesn’t block navbar text
            left: "15%",
            transform: "translateX(-50%)", // Ensures perfect horizontal centering
            width: "60%",
            maxWidth: "500px",
            backgroundColor: "#fff",
            borderRadius: "25px",
            boxShadow: "0px 4px 10px rgba(0,0,0,0.1)",
            padding: "10px 20px",
            display: "flex",
            alignItems: "center",
            zIndex: 1250,
          }}
        >
          <SearchIcon sx={{ color: "#6B4F4F", marginRight: 1 }} />
          <TextField
            variant="standard"
            placeholder="Search..."
            fullWidth
            InputProps={{
              disableUnderline: true,
              sx: { fontSize: "16px" },
            }}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
          <IconButton onClick={() => setSearchOpen(false)}>
            <CloseIcon sx={{ color: "#6B4F4F" }} />
          </IconButton>
        </Box>
      </Slide>
    </>
  );
}


